def validate_input(data):
    if not isinstance(data, dict):
        return False
    if 'name' not in data or not isinstance(data['name'], str):
        return False
    for key, value in data.items():
        if not isinstance(key, str) or not isinstance(value, str):
            return False
    return True

# Example usage
product_data = {"name": "Sample Product", "description": "A sample product description"}
print(validate_input(product_data))  # Should print True
